<div class="event-admin-heading"><div><span class="admin-overline">AGENDA DAN PEMBINAAN</span><h1>Kelola kegiatan</h1><p>Atur jadwal, kuota, publikasi, dan peserta kegiatan UMKM.</p></div><a class="event-primary" href="<?= site_url('pengelola/kegiatan/baru') ?>">+ Buat kegiatan</a></div>
<section class="event-admin-card"><div class="event-section-head"><h2>Daftar kegiatan</h2><span><?= (int)$total ?> kegiatan</span></div><form class="staff-list-filter" method="get" action="<?= site_url('pengelola/kegiatan') ?>"><label>Cari kegiatan<input type="search" name="q" value="<?= html_escape($search) ?>" maxlength="80" placeholder="Judul atau tempat"></label><label>Status<select name="status"><option value="">Semua</option><?php foreach(array('draft'=>'Draf','published'=>'Terbit') as $value=>$label): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php $this->load->view('staff/_list_size',array('per_page'=>$per_page)); ?><button type="submit">Terapkan</button><a href="<?= site_url('pengelola/kegiatan') ?>">Reset</a></form><?php if(!$events): ?><div class="event-empty">Belum ada kegiatan. Buat agenda pertama untuk memulai.</div><?php endif; ?><div class="event-admin-list"><?php foreach($events as $event): ?><article class="event-admin-row"><div class="event-admin-date"><strong><?= date('d',strtotime($event['starts_at'])) ?></strong><small><?= html_escape(date('M Y',strtotime($event['starts_at']))) ?></small></div><div class="event-admin-row-copy"><div><span class="event-badge <?= $event['status']==='published'?'live':'' ?>"><?= $event['status']==='published'?'Terbit':'Draf' ?></span><?php if($event['capacity']): ?><span class="event-muted"><?= (int)$event['taken'] ?>/<?= (int)$event['capacity'] ?> peserta</span><?php else: ?><span class="event-muted"><?= (int)$event['taken'] ?> peserta</span><?php endif; ?></div><h3><?= html_escape($event['title']) ?></h3><p><?= html_escape($event['venue']?:($event['district_name']?:'Lokasi menyusul')) ?></p></div><div class="event-admin-actions"><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/peserta') ?>">Peserta</a><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/studio') ?>">Studio</a><a href="<?= site_url('pengelola/kegiatan/'.$event['id'].'/ubah') ?>">Ubah</a><?php if($event['status']==='published'): ?><a href="<?= site_url('kegiatan/'.$event['slug']) ?>" target="_blank" rel="noopener">Lihat ↗</a><?php endif; ?></div></article><?php endforeach; ?></div><?php $this->load->view('staff/_pagination',array('base'=>site_url('pengelola/kegiatan'),'params'=>array('q'=>$search,'status'=>$status,'per_page'=>$per_page),'page'=>$page,'pages'=>$pages)); ?></section>
